# find ORFs (ATG to stop) in 6 frames, length > 100 aa
def orfs(s, strand, name):
    res=[]
    L=len(s)
    for f in range(3):
        t=translate(s[f:])
        i=0
        while True:
            m=t.find('M',i)
            if m<0: break
            stp=t.find('*',m)
            if stp<0: stp=len(t)
            if stp-m>=100:
                res.append((name,f,m,stp,stp-m))
            i=m+1
